async function updateCustomerGroup(records, title, getPatch) {
  if (!records.length) throw new Error('请先勾选需要处理的客户');
  const results = [];
  for (const c of records) { try { await api(`/api/clients/${c.id}`, { method: 'PATCH', body: { ...getPatch(c), version: c.version } }); results.push({ id: c.id, name: c.name, ok: true }); } catch (error) { results.push({ id: c.id, name: c.name, ok: false, error: errorText(error) }); } }
  selectionSet('clients').clear();
  try { await reload(); } catch (error) { toast(`处理已结束，列表刷新失败：${error.message}`, 'error'); }
  setTimeout(() => modal(`${title}结果`, `<div class="notice" data-customer-update-results>本次处理 ${results.length} 家，成功 ${results.filter(r => r.ok).length} 家，未更新 ${results.filter(r => !r.ok).length} 家。</div>${table(['客户', '结果', '说明'], results.map(r => `<tr data-customer-update-id="${r.id}" data-result-ok="${r.ok}"><td>${escape(r.name)}</td><td>${r.ok ? '已更新' : '未更新'}</td><td class="wrap">${escape(r.error || '保存完成')}</td></tr>`))}`), 10);
}
