function complianceIssues() {
  const issues = []; const cs = filteredClients();
  for (const c of cs) { const d = periodData(c); if (!c.accountant_id) issues.push({ c, rule: '客户归属', severity: 'warn', text: '未分配记账会计', action: 'client-edit' }); if (!c.code || !c.start_period) issues.push({ c, rule: '基础资料', severity: 'bad', text: '缺少客户编码或启用期间', action: 'client-edit' }); const pending = d.invoice.filter(i => i.status !== 'posted'); if (pending.length) issues.push({ c, rule: '票据制证', severity: 'warn', text: `${pending.length} 张票据尚未生成凭证`, action: 'invoice-client' }); if (Number(d.book?.unreviewed_count || 0)) issues.push({ c, rule: '凭证审核', severity: 'warn', text: `${d.book.unreviewed_count} 张凭证未审核`, action: 'open-book' }); for (const t of d.tax) { if (t.status === 'submitted' && !t.reference && !t.attachment_id) issues.push({ c, rule: '申报证据', severity: 'bad', text: `${t.tax_type} 已登记申报但缺少回执或附件`, action: 'tax-client' }); if (Number(t.paid_fen || 0) > Number(t.amount_fen || 0)) issues.push({ c, rule: '税务金额', severity: 'warn', text: `${t.tax_type} 实缴大于应缴，请核对原始凭证`, action: 'tax-client' }); } }
  return issues;
}
function renderCompliance() { const issues = complianceIssues(); const rules = [['客户归属', '每个服务客户应指定记账会计。'], ['基础资料', '检查客户编码、会计制度与账套启用期间。'], ['票据制证', '检查本期已登记但尚未制证的票据。'], ['凭证审核', '按活动凭证检查待审核数量；会计完整性检查请进入账簿。'], ['申报证据', '已登记申报必须有回执号或证据附件。'], ['税务金额', '对实缴大于应缴的登记记录提示复核。']]; return `${filterControls()}<div class="notice">这是针对本地数据的可解释规则检查；不等同于税务机关审核或专业合规意见。账簿内另提供试算平衡、报表勾稽与期末检查。</div>${stats([['检查客户', filteredClients().length], ['本期异常', issues.length], ['需处理', issues.filter(i => i.severity === 'bad').length], ['待复核', issues.filter(i => i.severity === 'warn').length]])}<section class="panel"><div class="panel-title"><h2>${S.sub}</h2>${btn('重新检查', 'refresh', '', 'btn-primary')}</div>${S.sub === '规则检查' ? `<div class="split-grid">${rules.map(([t, d]) => `<div class="rule-card"><h3>${icon('check')} ${t}</h3><p>${d}</p></div>`).join('')}</div>` : ''}${table(['客户', '检查项', '级别', '发现的问题', '处理入口'], issues.map(i => tr([escape(i.c.name), escape(i.rule), tag(i.severity === 'bad' ? '需处理' : '待复核', i.severity), escape(i.text), link('前往处理', i.action, `data-id="${i.c.id}"`)])), '当前筛选范围内没有触发上述规则。')}</section>`; }
function renderProjects() { const ids = new Set(filteredClients().map(c => Number(c.id))); const list = arr('projects').filter(p => ids.has(Number(p.client_id))); const statuses = { pending: '未开始', in_progress: '处理中', completed: '已完成', terminated: '已终止' }; const rows = list.map(p => { const steps = p.steps || []; return tr([escape(clientName(p.client_id)), escape(p.name), escape(p.type), escape(p.due_date || '—'), escape(userName(p.assignee_id)), tag(statuses[p.status] || p.status, p.status === 'completed' ? 'good' : 'info'), `${steps.filter(s => s.done).length} / ${steps.length}`, `<div class="project-steps">${steps.map((s, i) => `<button class="step ${s.done ? 'done' : ''}" data-action="project-step" data-id="${p.id}" data-index="${i}" title="${escape(s.note || '')}">${s.done ? '✓' : '○'} ${escape(s.title)}</button>`).join('') || '<span class="muted">未设置步骤</span>'}</div>`, link('编辑项目', 'project-edit', `data-id="${p.id}"`)]); }); return `${filterControls({ includeClient: true })}${stats([['项目总数', list.length], ['处理中', list.filter(p => p.status === 'in_progress').length], ['已完成', list.filter(p => p.status === 'completed').length], ['未完成步骤', list.reduce((n, p) => n + (p.steps || []).filter(s => !s.done).length, 0)]])}<section class="panel"><div class="panel-title"><h2>${S.sub}</h2>${btn('新建工商项目', 'project-new', '', 'btn-primary')}</div><div class="notice">步骤完成会记录实际操作者和时间。点击步骤可更新完成状态；项目状态由项目负责人明确登记。</div>${entityTable('projects', list, ['客户', '项目名称', '类型', '截止日期', '负责人', '项目状态', '步骤进度', '办理步骤', '操作'], rows, '暂无项目', btn('建立首个项目', 'project-new', '', 'btn-primary'))}</section>`; }
