function riskClients(type, cs = filteredClients()) { if (type === 'book') { const months = monthRange(S.period, 3); return cs.filter(c => c.start_period <= months[0] && months.every(p => !arr('book_periods').some(b => Number(b.client_id) === Number(c.id) && b.period === p && Number(b.voucher_count) > 0))); } if (type === 'tax') return cs.filter(c => periodData(c).states[3] === 0 || periodData(c).tax.filter(t => !/个税|个人所得|^IIT$/i.test(t.tax_type)).every(t => t.status === 'pending')); return cs.filter(c => arr('contracts').some(r => Number(r.client_id) === Number(c.id) && Number(r.debt_fen) > 0)); }
function renderRiskDetection(cs) { const types = [['book', '未记账', '启用至少三个月且最近三个月没有活动凭证', 'orange'], ['tax', '未报税', '本期非个税申报未登记或尚未开始（本地记录）', 'purple'], ['fee', '有欠款', '截至所选月份存在合同欠费的客户', 'red']]; const selected = S.detectType || 'book'; const counts = [0, 0, 0]; cs.forEach(c => counts[detectionState(c, selected)]++); const total = cs.length, a = total ? counts[0] / total * 360 : 0, b = total ? (counts[0] + counts[1]) / total * 360 : 0; const byUser = arr('users').map(u => { const mine = cs.filter(c => Number(c.accountant_id) === Number(u.id)); const values = [0, 0, 0]; mine.forEach(c => values[detectionState(c, selected)]++); return { name: u.name, values, total: mine.length }; }); const max = Math.max(1, ...byUser.map(u => u.total)); return `<section class="panel"><div class="panel-title"><h2>风险预警</h2><span class="muted small">统计截至 ${S.period} · 税务来源：人工 / 导入</span></div><div class="risk-grid">${types.map(([k, t, d, color]) => `<button class="risk-card ${color}" data-action="risk-details" data-type="${k}"><strong>${riskClients(k, cs).length}</strong><span>${t}</span><small>${d}</small></button>`).join('')}</div></section><section class="panel"><div class="section-tabs">${[['book', '记账'], ['tax', '报税'], ['fee', '收费']].map(([k, t]) => `<button data-action="detect-type" data-type="${k}" class="${selected === k ? 'active' : ''}">${t}</button>`).join('')}</div><div class="detection-grid"><div class="detection-donut"><div class="donut" style="--a:${a}deg;--b:${b}deg"><strong>${total}</strong></div><div class="legend vertical">${['未开始', '进行中', '已完成'].map((t, i) => `<span><i class="legend-${i}"></i>${t}　${counts[i]} 家</span>`).join('')}</div></div><div class="employee-chart"><div class="stack-chart">${byUser.map(u => `<div class="stack-column"><div class="stack-bar" title="${escape(u.name)}：${u.values.join(' / ')}"><i class="stack-0" style="height:${u.values[0] / max * 100}%"></i><i class="stack-1" style="height:${u.values[1] / max * 100}%"></i><i class="stack-2" style="height:${u.values[2] / max * 100}%"></i></div><label>${escape(u.name)}</label><small>${u.total} 家</small></div>`).join('')}</div><p class="muted small" style="text-align:center">员工负责客户的实际状态分布 · 未分配客户不计入员工柱图</p></div></div></section>`; }
async function agentForm(id) { const a = id ? entity('tax_agents', id) : { client_id: '', role: '办税联系人' }; return modal(id ? '编辑办税联系人' : '新增办税联系人', `<div class="form-grid">${field('姓名 *', 'name', a.name, 'text', 'required')}${field('联系电话', 'phone', a.phone, 'tel')}${selectField('启用状态','enabled',[['1','已启用'],['0','已停用']],a.enabled === false || a.enabled === 0 ? '0' : '1')}${field('角色 / 分工', 'role', a.role)}${selectField('关联客户', 'client_id', [['', '机构通用'], ...clients().map(c => [c.id, c.name])], a.client_id)}${textarea('备注', 'note', a.note)}</div>`, async form => { const v = formData(form); await saved(id ? `/api/tax-agents/${id}` : '/api/tax-agents', { name: v.name, phone: v.phone, role: v.role, enabled: v.enabled !== '0', client_id: v.client_id ? Number(v.client_id) : null, note: v.note, ...(id ? { version: a.version } : {}) }, id ? 'PATCH' : 'POST'); }); }
async function requestForm(id) { const r = id ? entity('invoice_requests', id) : { client_id: S.clientId, status: 'draft', amount_fen: 0, tax_fen: 0 }; return modal(id ? '编辑本地开票申请' : '新建本地开票申请', `<div class="notice warn">仅保存申请资料，不是有效税务发票，不会连接开票平台。</div><div class="form-grid">${selectField('客户 *', 'client_id', clientOptions(), r.client_id)}${selectField('申请状态', 'status', [['draft', '草稿'], ['ready', '资料已备妥']], r.status)}${field('购买方名称', 'buyer_name', r.buyer_name)}${field('购买方税号（可空）', 'buyer_tax_no', r.buyer_tax_no)}${field('不含税金额', 'amount', plainMoney(r.amount_fen), 'number', 'min="0" step="0.01" required')}${field('税额', 'tax', plainMoney(r.tax_fen), 'number', 'min="0" step="0.01" required')}${textarea('开票内容', 'content', r.content)}${textarea('备注', 'note', r.note)}</div>`, async form => { const v = formData(form); if (!v.client_id) throw new Error('请选择客户'); await saved(id ? `/api/invoice-requests/${id}` : '/api/invoice-requests', { client_id: Number(v.client_id), buyer_name: v.buyer_name, buyer_tax_no: v.buyer_tax_no, content: v.content, amount_fen: fen(v.amount), tax_fen: fen(v.tax), status: v.status, note: v.note, ...(id ? { version: r.version } : {}) }, id ? 'PATCH' : 'POST'); }); }
async function assignLabels() { const label = $('#batch-label')?.value; const mode = $('#label-mode')?.value; const eligible = new Set(filteredClients().map(c => Number(c.id))); const ids = [...S.labelSelectedIds].filter(id => eligible.has(id)); if (!label || !ids.length) throw new Error('请选择全局标签并勾选客户'); const failed = []; for (const id of ids) { const c = client(id); const labels = mode === 'remove' ? (c.labels || []).filter(l => l !== label) : [...new Set([...(c.labels || []), label])]; try { await api(`/api/clients/${id}`, { method: 'PATCH', body: { labels, version: c.version } }); } catch (e) { failed.push(`${c.name}：${e.message}`); } } await reload(); if (failed.length) await modal('标签批量更新结果', `<div class="notice">成功 ${ids.length - failed.length} 家，失败 ${failed.length} 家。</div><p style="white-space:pre-wrap">${escape(failed.join('\n'))}</p>`); else toast(`已更新 ${ids.length} 家客户的标签`); }

